<?php require_once __DIR__.'/../../config/app.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/pages/products/index.php');$d=['product_code'=>strtoupper(trim($_POST['product_code']??'')),'product_name'=>trim($_POST['product_name']??''),'category'=>$_POST['category']??'','unit'=>$_POST['unit']??'','price'=>$_POST['price']??'','stock'=>$_POST['stock']??'','entry_date'=>$_POST['entry_date']??'','description'=>trim($_POST['description']??'')];$er=[];foreach(['product_code','product_name','category','unit','price','stock','entry_date','description'] as $k)if($d[$k]==='')$er[$k]='Kolom wajib diisi.';if(strlen($d['product_code'])>10)$er['product_code']='Kode maksimal 10 karakter.';if(!in_array($d['category'],['Food','Drink','Stationery','Uniform'],true))$er['category']='Kategori tidak valid.';if(!in_array($d['unit'],['Pcs','Pack','Bottle'],true))$er['unit']='Satuan tidak valid.';if(!is_numeric($d['price'])||$d['price']<0)$er['price']='Harga harus berupa angka dan tidak boleh negatif.';if(filter_var($d['stock'],FILTER_VALIDATE_INT)===false||$d['stock']<0)$er['stock']='Stok harus bilangan bulat dan tidak boleh negatif.';if(!validateDateValue($d['entry_date']))$er['entry_date']='Tanggal tidak valid.';$check=$pdo->prepare('SELECT product_id FROM products WHERE product_code=?');$check->execute([$d['product_code']]);if($check->fetch())$er['product_code']='Nilai sudah digunakan.';if($er)failForm($er,$d,'/pages/products/create.php');try{$pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO products (product_code,product_name,category,unit,price,stock,entry_date,description) VALUES (?,?,?,?,?,?,?,?)');$stmt->execute(array_values($d));$pdo->commit();$_SESSION['success']='Data berhasil ditambahkan.';redirect('/pages/products/index.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();if($e->getCode()==='23000')failForm(['form'=>'Data duplikat atau melanggar aturan database.'],$d,'/pages/products/create.php');throw $e;}